  {'title':'Hansen and Scheinkman, Back to the Future: Generating Moment Implications for Continuous-Time Markov Processes','url':'https://www.nber.org/papers/t0141','note':'Proposition 5.5 of the 1993 working paper identifies a selfadjoint generator from its fixed-lag transition operator. This reversible identification result is prior work.'},
  {'title':'Crommelin and Vanden-Eijnden, Reconstruction of diffusions using spectral data from timeseries','url':'https://doi.org/10.4310/CMS.2006.v4.n3.a9','note':'An established spectral-fitting approach to diffusion reconstruction, including nonparametric formulations.'},
